#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    long long countDistinct(long long n) {
        string s = to_string(n);
        int len = s.size();
        vector<long long> pow9(len + 1, 1);
        for (int i = 1; i <= len; ++i) pow9[i] = pow9[i-1] * 9;
        long long ans = 0;
        for (int i = 1; i < len; ++i) ans += pow9[i];
        for (int i = 0; i < len; ++i) {
            int d = s[i] - '0';
            ans += (long long)max(0, d - 1) * pow9[len - i - 1];
            if (d == 0) return ans;
        }
        return ans + 1;
    }
};
